async function run(fn){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){message(e.message);}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);paint();}}
async function refresh(reset=false){state=await api('state');if(!draft||reset){draft=state.draft;revision=state.revision;step=1;saved=false;restore();}else restore();$('cliVersion').textContent=state.cli_version;$('environment').replaceChildren();for(const text of ["作業系統："+(state.windows?"Windows，符合此版本範圍":"目前僅驗證Windows"), 'Node.js：'+state.node+(state.node_ok?"，符合版本":"，請安裝24.19以上的24系列"), "必要套件："+state.dependencies.filter(d=>d.ok).length+'／'+state.dependencies.length+" 項已準備", "資料："+state.data+(state.running?"；本副本有執行中或尚未核對的連線，請先停止再改設定。":"；不會匯入其他環境的資料。")]){const p=document.createElement('p');p.textContent=text;$('environment').append(p);}paint();}
document.querySelectorAll('#brain input,#localFields input,#localFields select,#codexTools,#timezone,#reportSchedule').forEach(e=>e.addEventListener('change',()=>{draft=input();saved=false;paint();}));
$('refresh').onclick=()=>run(async()=>{await refresh();message("檢查完成。選擇保留，沒有保存或啟動。");});$('reload').onclick=()=>run(async()=>{await refresh(true);message("已讀取保存的設定，未保存的選擇已捨棄。");});
$('install').onclick=()=>run(async()=>{message("正在依鎖定版本安裝必要套件，請等待，不必重按。");await api('install',{});await refresh();message("套件安裝完成。下一步：選擇大腦。");});
$('models').onclick=()=>run(async()=>{draft=input();message("只檢查本機服務資訊與模型清單；不載入模型。");const r=await api('models',{endpoint:draft.endpoint});$('model').replaceChildren(new Option("請選擇一個已安裝模型",''));for(const m of r.models)$('model').add(new Option(m.name,m.name));if(r.models.some(m=>m.name===draft.model))$('model').value=draft.model;draft=input();$('modelState').textContent="服務 "+r.service_version+"；找到 "+r.models.length+" 個本機模型。尚未驗證完整生活能力。";message(r.models.length?"請選擇模型後繼續。":"尚未找到本機模型。請自行在Ollama安裝模型後，再按檢查；本導引不會下載。");});
$('checkCodex').onclick=()=>run(async()=>{message("正在檢查版本與登入，不呼叫模型。");const r=await api('check',{draft:{...input(),mode:'codex',codex_tools:false}});message(r.checks.map(c=>c.message).join('\n'));});
$('installCodex').onclick=()=>run(async()=>{const started=Date.now();let polling=false;const progress=setInterval(async()=>{if(polling)return;polling=true;try{const s=await api('state'),p=s.operation?.progress;message(p?.stage==='download'?"正在下載Codex："+(p.bytes/1000000).toFixed(1)+'／'+(p.total/1000000).toFixed(1)+" MB。片段會保留，可於中斷後繼續。":p?.stage==='verify'?"下載完成，正在核對官方SHA-512完整性；尚未安裝。":p?.stage==='install'?"完整性校驗已通過，正在安裝到本副本。":"正在準備指定版本，已等待 "+Math.floor((Date.now()-started)/1000)+" 秒。最多等待10分鐘；不必重按。");}catch{}finally{polling=false;}},1000);message("正在安裝指定版本；不更新全域或共用程式。");try{const r=await api('install-codex',{});clearInterval(progress);message('Codex '+r.version+" 已安裝。下一步：自行登入，然後檢查。");}finally{clearInterval(progress);}});
