$('next').onclick=()=>run(async()=>{draft=input();if(step===2){message("檢查選定的大腦接頭；不執行推理。");const r=await api('check',{draft:{...draft,codex_tools:false}});if(!r.ok)throw Error(r.checks.filter(c=>!c.ok).map(c=>c.message).join('\n'));}if(step===3){message("正在檢查並準備設定摘要…");const r=await api('check',{draft});if(!r.ok)throw Error(r.checks.filter(c=>!c.ok).map(c=>c.message).join('\n'));$('review').replaceChildren();for(const [label,k]of [["生活時區",'timezone'],["大腦",'brain'],["工具",'tools'],["自己的資料位置",'data'],["報告",'reports'],["這次影響",'effect']]){const p=document.createElement('p');p.textContent=label+'：'+(globalThis.kinseedI18n?.label(r.summary[k])??r.summary[k]);$('review').append(p);}}step++;message("目前選擇已保留在這個瀏覽器分頁；尚未保存設定或啟動個體。");paint();});
$('save').onclick=()=>run(async()=>{draft=input();message("正在核對並保存設定…");const r=await api('save',{draft,revision});revision=r.revision;saved=true;step=5;$('savedState').textContent="設定已保存。"+r.summary.effect+(r.backup?" 原設定已有備份。":'');message("保存完成。下一步：啟動自己的控制台。");paint();});
