 constructor(platform){this.p=platform;this.gmail=new GmailSendOnly(path.join(platform.dir,'private-connections'));this.media=new HedraResults(this);this.mediaLab=new MediaLab(this);this.audioUnderstanding=new AudioUnderstanding(this);this.whisperService=new WhisperService(path.join(platform.dir,'whisper-service'));this.pending=new Map();this.imports=new Map();this.endpoint=null;this.hedra=new HedraManager(path.join(platform.dir,'hedra.sqlite'),{now:()=>platform.now(),engineering:platform.engineering,resolveReference:(key,id)=>ownReference(this,key,id),resolve:key=>{const e=this.p.entity(key),c=e.store.get('control');let can_submit=false;try{e.store.verify();can_submit=!this.p.global().stopped&&!this.p.runtimeHold&&!e.fatal&&!e.stopping&&!c.stop_lock&&c.mode==='running'&&e.now()<c.authorization_until&&windowAt(c,e.now()).open;}catch{}return {life_hash:hash(optional(e,'life',null)),can_submit};},emit:(key,event)=>{const e=this.p.entity(key);e.store.tx(()=>{const receipt='hedra-event:'+event.event_id;if(e.store.receipt(receipt))return;e.store.event('hedra.'+event.type,{...event,daily_authority_preserved:true},'controller');e.store.putReceipt(receipt,{delivered:true});});}});}
 entity(key){const e=this.p.entity(key);initializeHub(e);return e;}
 binding(){const b=this.p.brainBinding??{adapter:'unconfigured',model:'unconfigured'};return hash({adapter:b.adapter,model:b.model,endpoint:this.p.toolBrainEndpoint??null});}
