 get(e,key,version){initializeHub(e);const r=version?e.store.db.prepare('SELECT body FROM hub_objects WHERE id=? AND version=?').get(key,version):e.store.db.prepare('SELECT body FROM hub_objects WHERE id=? ORDER BY version DESC LIMIT 1').get(key);if(!r)throw Error('找不到這個個體的項目或版本。');return body(r);}
 list(e,kind){initializeHub(e);return e.store.db.prepare('SELECT body FROM hub_objects o WHERE version=(SELECT max(version) FROM hub_objects WHERE id=o.id) ORDER BY rowid DESC').all().map(body).filter(x=>!kind||x.kind===kind);}
 put(e,kind,data,{object_id=id(),expected_version=0}={}){const previous=e.store.db.prepare('SELECT max(version) v FROM hub_objects WHERE id=?').get(object_id)?.v??0;if(previous!==expected_version)throw Error('內容已有新版本，請重新載入後保存。');const value={...data,id:object_id,kind,version:previous+1,at:e.now()},text=JSON.stringify(value),used=e.store.db.prepare('SELECT coalesce(sum(length(CAST(body AS BLOB))),0) n FROM hub_objects').get().n;if(used+Buffer.byteLength(text)>HUB_LIMITS.storage_bytes)throw Error('此個體工具資料已達20MB，請先由Owner檢視保存量；未刪除歷史。');e.store.db.prepare('INSERT INTO hub_objects VALUES(?,?,?,?)').run(object_id,value.version,kind,text);return value;}
 record(e,type,value,l){const {data_base64,text,files,paragraphs,rows,...safe}=value;return e.store.event('hub.'+type,safe,l?'mcp':'owner',l??{});}
 transaction(e,request_id,input,fn){if(typeof request_id!=='string'||!request_id||request_id.length>100)throw Error('請提供工作識別碼。');const key='hub:'+request_id,prior=e.store.receipt(key),digest=hash(input);if(prior){if(prior.input_hash!==digest)throw Error('同一請求內容不同，沒有覆蓋或重做。');return prior.result;}return e.store.tx(()=>{const result=fn();e.store.putReceipt(key,{input_hash:digest,result});return result;});}
 hedraSummary(e){const r=this.hedra.snapshot(e.info.individual_id),saved=this.list(e,'hedra-media');r.jobs=r.jobs.map(j=>{const results=saved.filter(x=>x.source.job_id===j.id).map(x=>this.media.metadata(x));const downloaded=j.outputs.length>0&&results.length===j.outputs.length;const row=e.store.db.prepare("SELECT body FROM events WHERE json_extract(body,'$.type') IN ('hub.hedra_download_failed','hub.hedra_download_started','hub.hedra_download_saved') AND json_extract(body,'$.result.job_id')=? ORDER BY seq DESC LIMIT 1").get(j.id);const event=row?JSON.parse(row.body):null;return {...j,results,downloaded,download_status:downloaded?'saved':event?.type==='hub.hedra_download_failed'?'download_failed':'not_saved',download_error:event?.type==='hub.hedra_download_failed'?event.result.message:null,message:downloaded?'遠端成果已完成，本機副本已保存；不代表模型已檢視。':j.message};});return r;}
 summary(e){const items=this.list(e).map(({data_base64,text,files,paragraphs,rows,...rest})=>rest);return {audio_understanding:this.audioUnderstanding.summary(e,{owner:true}),media_lab:this.mediaLab.summary(e),hedra:this.hedraSummary(e),permissions:this.permissions(e),limits:HUB_LIMITS,binding:this.binding(),items,gmail:this.gmail.status(),services:['wikipedia','crossref','usgs'],cloud:optional(e,'hub_cloud',{state:'not_connected',service:'',folder:'',read:false,write:false}),package_catalog:VERIFIED_PACKAGES,catalog:hubTools.map(t=>({name:t.name,description:t.description})),vision:{ocr:'local_tesseract',model:this.p.brainBinding?.adapter==='codex-cli'?'MCP影像輸入，需核對本輪模型結果':'目前接頭未驗證影像輸入，不假裝支援'}};}
