 async importMaterial(e,b){if(typeof b.request_id!=='string'||!b.request_id||b.request_id.length>100)throw Error('請提供工作識別碼。');const digest=hash(b),prior=e.store.receipt('hub:'+b.request_id);if(prior){if(prior.input_hash!==digest)throw Error('同一請求內容不同，沒有重做。');return prior.result;}const key=e.info.individual_id+':'+b.request_id,active=this.imports.get(key);if(active){if(active.digest!==digest)throw Error('同一請求內容不同。');return active.promise;}const promise=this.performImport(e,b);this.imports.set(key,{digest,promise});try{return await promise;}finally{this.imports.delete(key);}}
