 if(!bytes.length||bytes.length>HUB_LIMITS.file_bytes)throw Error('材料必須介於1位元組至8MB。');let text=null;const ext=b.name.split('.').at(-1).toLowerCase();if(['txt','md','csv','json'].includes(ext)||mime.startsWith('text/')){mime=ext==='csv'?'text/csv':'text/plain';text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);}else if(ext==='pdf'&&bytes.subarray(0,5).toString()==='%PDF-'||['docx','xlsx'].includes(ext)){const parsed=await parseDocument(bytes,ext);mime=parsed.mime;text=parsed.text;}else if(bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))mime='image/png';else if(bytes[0]===255&&bytes[1]===216)mime='image/jpeg';else throw Error('目前接受UTF-8文字、PDF、Word、Excel、PNG及JPEG；不執行匯入檔案。');
 if(mime.startsWith('image/'))imageDimensions(bytes,mime);if(text&&text.length>1000000)throw Error('解析文字超過100萬字元，請分批。');if(b.consent===true&&b.destination!==this.binding())throw Error('目前大腦已變更，請重新核對分析目的地。');return this.transaction(e,b.request_id,b,()=>{const value=this.put(e,'material',{name:b.name,mime,bytes:bytes.length,sha256:hash(bytes),data_base64:bytes.toString('base64'),text,source,consent:b.consent===true,destination:b.consent===true?this.binding():null});this.record(e,'material_imported',value);return {id:value.id,version:value.version,name:value.name,bytes:value.bytes,sha256:value.sha256,consent:value.consent};});}
