 async tool(e,name,b,l){initializeHub(e);e.assertAllowed(l);const required={material_list:'materials',material_read:'materials',project_save:'projects',project_run:'projects',document_create:'documents',data_query:'data',image_read:'vision',image_view:'vision',mail_draft:'mail'}[name];if(required)this.require(e,required);if(name==='data_query'&&!e.store.get('control').permissions.web)throw Error('公開資料查詢仍須原有外網權限。');
 if(name.startsWith('audio_analysis_')){this.require(e,'media');this.require(e,'hearing');if(name==='audio_analysis_request')return this.audioUnderstanding.request(e,b);if(name==='audio_analysis_status'){const j=this.get(e,b.job_id);if(j.kind!=='audio-analysis')throw Error('不是聲音分析工作。');if(j.brain_binding!==this.binding())throw Error('聲音分析尚未同意交給目前大腦。');if(j.state==='completed')this.record(e,'audio_analysis_provided',{id:j.id,result_hash:hash(j.result),brain_binding:this.binding()},l);return this.audioUnderstanding.public(j);}}
 if(name==='hedra_voices'){outboundGuard(b.query,networkProtected(e));if(!this.hedra.ledger.connection().enabled)throw Error('Owner尚未啟用Hedra連線。');return this.hedra.provider.voices(b.model,b.query);}
