(body,'$.type')='hub.media_frame_provided' AND json_extract(body,'$.result.id')=?").get(f.id))))throw Error('先取得這個成品的擷取畫面，再記錄視覺核對。');return this.transaction(e,b.request_id,b,()=>{const v=this.put(e,'media-review',{name:x.name+'核對',source_id:x.id,source_sha256:x.sha256,visual_reviewed:b.visual_reviewed,frame_ids:b.frame_ids??[],audio_review:b.audio_review,audio_analysis_ids:b.audio_analysis_ids??[],notes:b.notes,author:'individual'});this.record(e,'media_review_saved',{id:v.id,source_id:x.id,visual_reviewed:b.visual_reviewed,audio_review:b.audio_review},l);return {id:v.id,version:v.version};});}}
