 if(name==='project_save'){projectFiles(b.files,b.entry);return this.transaction(e,b.request_id,b,()=>{const x=this.put(e,'project',{name:cleanName(b.name),language:b.language,entry:b.entry,files:b.files},{object_id:b.project_id??id(),expected_version:b.expected_version});this.record(e,'project_saved',x,l);return {id:x.id,version:x.version,name:x.name,language:x.language};});}
