test('U24 installer subprocess cannot inherit API keys or parent cycle capabilities',async()=>{const a=process.env.KINSEED_CYCLE_TOKEN,b=process.env.OPENAI_API_KEY;try{process.env.KINSEED_CYCLE_TOKEN='SYNTHETIC_CAPABILITY';process.env.OPENAI_API_KEY='SYNTHETIC_KEY';const r=await runNode(['-e','console.log(JSON.stringify({cycle:!!process.env.KINSEED_CYCLE_TOKEN,key:!!process.env.OPENAI_API_KEY}))'],{cwd:APP_ROOT});assert(r.ok);assert.deepEqual(JSON.parse(r.detail.trim()),{cycle:false,key:false});}finally{if(a===undefined)delete process.env.KINSEED_CYCLE_TOKEN;else process.env.KINSEED_CYCLE_TOKEN=a;if(b===undefined)delete process.env.OPENAI_API_KEY;else process.env.OPENAI_API_KEY=b;}});
test('U25 official platform package bin layout is recognized without generic executable search',()=>{const f=fixture(),paths=npmBinaryCandidates(f.root);assert(paths.includes(path.join(f.root,'.private/codex-cli/node_modules/@openai/codex/vendor/x86_64-pc-windows-msvc/bin/codex.exe')));assert(paths.every(f=>f.endsWith('codex.exe')));});
test('U26 Windows bootstrap preserves CRLF and Git checkout requests the same encoding layout',()=>{const text=fs.readFileSync(path.join(APP_ROOT,'首次設定.cmd'),'utf8');assert(text.includes('\r\n'));assert(!/(?<!\r)\n/.test(text));assert(fs.readFileSync(path.join(APP_ROOT,'.gitattributes'),'utf8').includes('*.cmd text eol=crlf'));});

