test('F04 current version and historical text remain exact, independently labeled',()=>{const c={a:{version:7,memory:['先前版本是2'],plan:['舊計畫'],last_result:'舊結果'},identity_material:{complete:true,material:{conditions:[{raw_text:'身份原文'}]}},identity:{conditions:[{raw_text:'身份原文'}],sources:[{text:'另一項未重複來源'}]},authorization:{permissions:{note:false}},cycle:{deadline:99}};const before=structuredClone(c),x=guidedContext(c);assert.deepEqual(c,before);assert.equal(x.current_state.a.version,7);assert.deepEqual(x.historical_snapshot.memory,['先前版本是2']);assert.deepEqual(x.context.identity_material,c.identity_material);assert.deepEqual(x.context.identity.sources,c.identity.sources);assert.deepEqual(x.context.authorization,c.authorization);});
test('F05 incomplete approved material retains full index and read access',()=>{const c={a:{version:0,memory:[],plan:[]},identity_material:{complete:false},identity:{conditions:[{raw_text:'原文'}],read_tool:'read_identity_bundle'}};assert.deepEqual(guidedContext(c).context.identity,c.identity);});
const ledger=[{receipt_id:'r0',tool:'get_context',outcome:'success',automatic:true},{receipt_id:'r1',tool:'read_record',outcome:'error'},{receipt_id:'r2',tool:'write_note',outcome:'success'}];
