test('U06 saving cannot replace running config or remove active session',async()=>{const f=fixture(),env=loadEnvironment(f.root);fs.mkdirSync(env.home,{recursive:true});fs.writeFileSync(env.session,'{"preserve":true}');await assert.rejects(saveChoice(f.root,{draft:f.draft,revision:configRevision(f.root)}),/停止/);assert.equal(fs.readFileSync(env.session,'utf8'),'{"preserve":true}');});
test('U07 failed preflight never writes enabled settings',async()=>{const f=fixture();await assert.rejects(saveChoice(f.root,{draft:{...f.draft,mode:'codex'},revision:configRevision(f.root)},{preflight:async()=>({ok:false,error:'SYNTHETIC_NOT_LOGGED_IN'})}),/尚後|稍後/);assert.equal(fs.existsSync(path.join(f.root,'config/development.local.json')),false);});
test('U08 shared filesystem lock prevents two competing writers without deleting lock',async()=>{const f=fixture(),lock=path.join(f.root,'config/.setup-save.lock');fs.writeFileSync(lock,'retain');await assert.rejects(saveChoice(f.root,{draft:f.draft,revision:configRevision(f.root)}),/另一個設定程序/);assert.equal(fs.readFileSync(lock,'utf8'),'retain');});
test('U09 linked backup area is refused without touching external files',async()=>{const f=fixture(),outside=fs.mkdtempSync(path.join(APP_ROOT,'.private/setup-outside-'));fs.mkdirSync(path.join(f.root,'.private'));fs.symlinkSync(outside,path.join(f.root,'.private/setup-backups'),'junction');await assert.rejects(saveChoice(f.root,{draft:f.draft,revision:configRevision(f.root)}),/連結/);assert.deepEqual(fs.readdirSync(outside),[]);});
test('U10 model listing only uses version and tags, never pull/chat/show/load',async()=>{const requests=[],server=http.createServer((req,res)=>{requests.push(req.url);res.setHeader('content-type','application/json');res.end(JSON.stringify(req.url==='/api/version'?{version:'SYNTHETIC'}:{models:[{name:'synthetic-local',size:1},{name:'remote',remote_host:'cloud'}]}));});await new Promise(r=>server.listen(0,'127.0.0.1',r));try{const r=await localModels('http://127.0.0.1:'+server.address().port);assert.deepEqual(r.models.map(m=>m.name),['synthetic-local']);assert.deepEqual(requests.sort(),['/api/tags','/api/version']);assert.equal(r.inference_performed,false);}finally{await new Promise(r=>server.close(r));}});
test('U11 dependency installation fixes args, disables scripts and never global install',async()=>{const f=fixture();let args;await installDependencies(f.root,{run:async a=>{args=a;const p=JSON.parse(fs.readFileSync(path.join(f.root,'package.json')));for(const [name,version] of Object.entries(p.dependencies)){const dir=path.join(f.root,'node_modules',name);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'package.json'),JSON.stringify({version}));}return {ok:true};}});assert(args.includes('ci'));assert(args.includes('--ignore-scripts'));assert(!args.includes('-g'));assert(!args.some(x=>x.includes('codex@')));});
test('U12 Codex installation is pinned, isolated and refuses unknown preexisting prefix',async()=>{const f=fixture();let args;await installCodex(f.root,{run:async a=>{args=a;return {ok:true};},probe:()=>path.join(f.root,'.private/codex-cli/SYNTHETIC-NOT-A-REAL-BINARY.exe'),download:async()=>({verified:true,file:path.join(f.root,'.private/SYNTHETIC-ARTIFACT.tgz')})});assert(args.includes('--offline'));assert(args.includes(path.join(f.root,'.private/SYNTHETIC-ARTIFACT.tgz')));assert(args.includes(path.join(f.root,'.private/codex-cli')));assert(!args.includes('-g'));assert(npmBinaryCandidates(f.root).some(f=>f.includes('.private')));const other=fixture();fs.mkdirSync(path.join(other.root,'.private/codex-cli'),{recursive:true});fs.writeFileSync(path.join(other.root,'.private/codex-cli/keep.txt'),'retain');await assert.rejects(installCodex(other.root),/不會接管/);});
test('U13 web setup requires capability and rejects foreign Origin/Host',async()=>{const f=fixture(),app=await serveSetup({root:f.root});try{let r=await fetch(app.endpoint+'/api/state');assert.equal(r.status,401);r=await fetch(app.endpoint+'/api/state',{headers:{authorization:'Bearer '+app.token,Origin:'http://evil.test'}});assert.equal(r.status,400);const wrongHost=await new Promise((resolve,reject)=>{const q=http.request(app.endpoint+'/api/state',{headers:{authorization:'Bearer '+app.token,Host:'evil.test'}},res=>{res.resume();resolve(res.statusCode);});q.on('error',reject);q.end();});assert.equal(wrongHost,400);r=await fetch(app.endpoint+'/api/state',{headers:{authorization:'Bearer '+app.token}});assert.equal(r.status,200);}finally{await app.close();}});
test('U14 wizard saves without identity/birth/runtime and start rejects missing dependencies',async()=>{const f=fixture(),app=await serveSetup({root:f.root});const post=(url,b)=>fetch(app.endpoint+'/api/'+url,{method:'POST',headers:{authorization:'Bearer '+app.token,'content-type':'application/json'},body:JSON.stringify(b)});try{const r=await post('save',{draft:f.draft,revision:configRevision(f.root)});assert.equal(r.status,200);const b=await r.json();assert.equal((await post('start',{revision:b.revision})).status,400);assert(!fs.existsSync(loadEnvironment(f.root).runtime));}finally{await app.close();}});
test('U15 optional global tool switch is strict and old configs remain compatible',()=>{const f=fixture();assert.equal(loadEnvironment(f.root).config.tools,undefined);for(const tools of [{codex:{enabled:'yes'}},{codex:{enabled:false},extra:true},{codex:{enabled:false,endpoint:'x'}}]){const c={...loadEnvironment(f.root).config,tools};fs.writeFileSync(path.join(f.root,'config/development.local.json'),JSON.stringify(c));assert.throws(()=>loadEnvironment(f.root));fs.unlinkSync(path.join(f.root,'config/development.local.json'));}});
test('U16 same saved choice can be retried after lost response without extra backup',async()=>{const f=fixture(),revision=configRevision(f.root);await saveChoice(f.root,{draft:f.draft,revision});const r=await saveChoice(f.root,{draft:f.draft,revision});assert.equal(r.replayed,true);assert.equal(fs.readdirSync(path.join(f.root,'.private/setup-backups')).length,0);});
test('U17 changed default source is detected before first save',async()=>{const f=fixture(),revision=configRevision(f.root),file=path.join(f.root,'config/development.example.json'),c=JSON.parse(fs.readFileSync(file));c.http.port=58991;fs.writeFileSync(file,JSON.stringify(c));assert.notEqual(configRevision(f.root),revision);await assert.rejects(saveChoice(f.root,{draft:f.draft,revision}),/設定已在/);});
test('U18 disabled global Codex tool is absent from real MCP and rejects direct dispatch',async()=>{let fixture,done=false,error;fixture=await delegationFixture({runner:e=>async({token})=>{const m=controlledMCP({endpoint:fixture.app.endpoint,token,cwd:fixture.base});try{const list=await m.initialize();assert(!list.some(t=>t.name==='delegate_codex'));await e.tool(token,'get_context',{});await assert.rejects(e.tool(token,'delegate_codex',{request_id:'disabled',instruction:'synthetic',operations:['read'],inputs:[]}),/尚未設定Codex工具/);}catch(err){error=err;}finally{await m.close();done=true;}return {ok:false,local_exit_confirmed:true,synthetic:true};}});try{fixture.p.delegationEnabled=false;fixture.start();await until(()=>done&&!fixture.e.store.get('lease'));assert.ifError(error);assert.equal(fixture.e.store.get('control').cycles_used,1);assert.equal(fixture.p.global().worker,null);}finally{await fixture.app.close();}});
test('U19 source export contains exact lockfile and bootstrap, never private data or dependencies',()=>{const r=exportSource(APP_ROOT);assert.equal(fs.readFileSync(path.join(r.destination,'package-lock.json'),'utf8'),fs.readFileSync(path.join(APP_ROOT,'package-lock.json'),'utf8'));assert(fs.existsSync(path.join(r.destination,'首次設定.cmd')));assert(!fs.existsSync(path.join(r.destination,'.private')));assert(!fs.existsSync(path.join(r.destination,'node_modules')));assert(!fs.existsSync(path.join(r.destination,'config/development.local.json')));});
test('U20 source exporter refuses output outside private area or merging existing files',()=>{assert.throws(()=>exportSource(APP_ROOT,path.join(APP_ROOT,'not-private-export')),/private/);const dir=fs.mkdtempSync(path.join(APP_ROOT,'.private/existing-export-'));fs.writeFileSync(path.join(dir,'keep'),'retain');assert.throws(()=>exportSource(APP_ROOT,dir),/已存在/);assert.equal(fs.readFileSync(path.join(dir,'keep'),'utf8'),'retain');});
test('U21 missing lockfile is explained before running npm',async()=>{const f=fixture();fs.unlinkSync(path.join(f.root,'package-lock.json'));let count=0;await assert.rejects(installDependencies(f.root,{run:async()=>{count++;}}),/缺少package-lock/);assert.equal(count,0);});
test('U22 old marked session still blocks installation after manual data-path change',async()=>{const f=fixture(),env=loadEnvironment(f.root);fs.mkdirSync(env.home,{recursive:true});fs.writeFileSync(path.join(env.home,'instance.json'),JSON.stringify({kind:'kinseed-development-data',schema:1}));fs.writeFileSync(env.session,'{"preserve":true}');const c={...env.config,dataDirectory:'.private/other'};fs.writeFileSync(path.join(f.root,'config/development.local.json'),JSON.stringify(c));await assert.rejects(installDependencies(f.root,{run:async()=>{throw Error('MUST_NOT_RUN');}}),/停止/);assert.equal(fs.readFileSync(env.session,'utf8'),'{"preserve":true}');});
test('U23 dependency process success without correct installed versions is not reported installed',async()=>{const f=fixture();await assert.rejects(installDependencies(f.root,{run:async()=>({ok:true})}),/版本尚未全部符合/);});
test('U24 installer subprocess cannot inherit API keys or parent cycle capabilities',async()=>{const a=process.env.KINSEED_CYCLE_TOKEN,b=process.env.OPENAI_API_KEY;try{process.env.KINSEED_CYCLE_TOKEN='SYNTHETIC_CAPABILITY';process.env.OPENAI_API_KEY='SYNTHETIC_KEY';const r=await runNode(['-e','console.log(JSON.stringify({cycle:!!process.env.KINSEED_CYCLE_TOKEN,key:!!process.env.OPENAI_API_KEY}))'],{cwd:APP_ROOT});assert(r.ok);assert.deepEqual(JSON.parse(r.detail.trim()),{cycle:false,key:false});}finally{if(a===undefined)delete process.env.KINSEED_CYCLE_TOKEN;else process.env.KINSEED_CYCLE_TOKEN=a;if(b===undefined)delete process.env.OPENAI_API_KEY;else process.env.OPENAI_API_KEY=b;}});
test('U25 official platform package bin layout is recognized without generic executable search',()=>{const f=fixture(),paths=npmBinaryCandidates(f.root);assert(paths.includes(path.join(f.root,'.private/codex-cli/node_modules/@openai/codex/vendor/x86_64-pc-windows-msvc/bin/codex.exe')));assert(paths.every(f=>f.endsWith('codex.exe')));});
test('U26 Windows bootstrap preserves CRLF and Git checkout requests the same encoding layout',()=>{const text=fs.readFileSync(path.join(APP_ROOT,'首次設定.cmd'),'utf8');assert(text.includes('\r\n'));assert(!/(?<!\r)\n/.test(text));assert(fs.readFileSync(path.join(APP_ROOT,'.gitattributes'),'utf8').includes('*.cmd text eol=crlf'));});
